<template><div class="reference-pager"><span>共 {{ total }} 条</span><select :value="pageSize" @change="$emit('update:pageSize',Number($event.target.value));setPage(1)"><option v-for="n in [12,24,48,96]" :key="n" :value="n">{{ n }}条/页</option></select><button :disabled="page<=1" @click="setPage(page-1)">‹</button><button v-for="n in numbers" :key="n" :class="{active:page===n}" @click="setPage(n)">{{ n }}</button><span v-if="last>5">… {{ last }}</span><button :disabled="page>=last" @click="setPage(page+1)">›</button><label>前往 <input type="number" min="1" :max="last" v-model="jump" @change="setPage(jump)" @keyup.enter="setPage(jump)" /> 页</label><button title="刷新列表" @click="$emit('refresh')">↻</button></div></template>
<script setup>
import {computed,ref,watch} from 'vue';const props=defineProps({page:Number,pageSize:Number,total:Number});const emit=defineEmits(['update:page','update:pageSize','refresh']);const last=computed(()=>Math.max(1,Math.ceil(props.total/props.pageSize))),jump=ref(props.page);const numbers=computed(()=>{const start=Math.max(1,Math.min(props.page-2,last.value-4));return Array.from({length:Math.min(last.value,5)},(_,i)=>start+i);});function setPage(value){const n=Math.max(1,Math.min(last.value,Math.trunc(Number(value))||1));jump.value=n;emit('update:page',n);}watch(()=>props.page,n=>jump.value=n);watch(last,()=>{if(props.page>last.value)setPage(last.value);});
</script>
<style scoped>
.reference-pager{display:flex;align-items:center;gap:8px;font-size:12px;color:var(--ink-soft);margin-left:auto;white-space:nowrap;}.reference-pager select,.reference-pager input,.reference-pager button{font:inherit;border:1px solid var(--line);border-radius:3px;background:var(--surface);color:inherit;height:30px;box-sizing:border-box;}.reference-pager select{padding:0 10px;}.reference-pager button{padding:0 10px;cursor:pointer;}.reference-pager button:disabled{opacity:.4;cursor:not-allowed;}.reference-pager button.active{background:var(--list-accent,#1890ff);border-color:var(--list-accent,#1890ff);color:#fff;}.reference-pager input{width:42px;text-align:center;}.reference-pager label{display:flex;gap:5px;align-items:center;}@media(max-width:900px){.reference-pager{flex-wrap:wrap;margin-left:0;}}
</style>
